create role anon;create role authenticated;create role service_role bypassrls;
create schema cron;
create table cron.job(jobid bigint primary key,jobname text,command text,schedule text,active boolean);
insert into cron.job values(1,'lts_daily_backup_snapshot','select public.lts_backup_snapshot_take_v1(''00000000-0000-4000-8000-000000000001''::uuid,current_date);','15 6 * * *',true);
create function cron.alter_job(job_id bigint,command text) returns void language sql as $$update cron.job set command=$2 where jobid=$1$$;
