create table public.lts_backup_snapshot(user_id uuid,snapshot_date date,payload jsonb not null,payload_hash text not null,payload_bytes int not null,created_at timestamptz default now(),primary key(user_id,snapshot_date));
alter table public.lts_backup_snapshot enable row level security;
grant select,insert on public.lts_backup_snapshot to service_role;
create function public.lts_backup_snapshot_take_v1(p_user_id uuid,p_snapshot_date date) returns jsonb language plpgsql as $$declare j jsonb:=jsonb_build_object('format','lts-backup-v1','user_id',p_user_id,'accounts','[]'::jsonb);begin insert into public.lts_backup_snapshot(user_id,snapshot_date,payload,payload_hash,payload_bytes)values(p_user_id,p_snapshot_date,j,md5(j::text),octet_length(j::text))on conflict do nothing;return jsonb_build_object('ok',true);end$$;
grant select on all tables in schema public to service_role;
grant usage on schema public to service_role;
